import re
L=open('references/project-standards.md').read().split('\n')
heads=[(i,l) for i,l in enumerate(L) if l.startswith('## ')]
def head(i):
    h=None
    for j,l in heads:
        if j<=i: h=(j+1,l)
        else: break
    return h
for pid in ['OR-1c','OR-5b','OR-6c','OR-14b','OR-17b','OR-22b','OR-23b','OR-25','OT-2','OR-10b','OW-1b','OW-1c']:
    seen={}
    for i,l in enumerate(L):
        if re.search(r'(?<![\w-])'+re.escape(pid)+r'(?![\w-])',l):
            h=head(i); seen.setdefault(h,[]).append(i+1)
    print('==',pid)
    for h,ls in seen.items(): print('  ',h[0],h[1][:110],'| lines',ls[:4])
EOF

