function rulingParts(id, text) {
  const lines = text.split("\n"), words = [], clean = (x) => x.replace(/\*\*/g, "").replace(/`/g, "");
  const unq = (x) => x.replace(/^>\s?/, "").replace(/^"|"$/g, "");
  // Shape 1: a line `ID: "words"` (optionally numbered), or `ID:` followed by quoted `>` lines.
  const own = new RegExp("^(?:\\d+\\.\\s*)?(?:\\*\\*)?" + id + "[.:]\\*?\\*?\\s*(.*)$");
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(new RegExp("^(?:\\d+\\.\\s*)?" + id + ":\\s*(.*)$"));
    if (!m) continue;
    if (m[1]) words.push(m[1].replace(/^"|"$/g, ""));
    else for (let j = i + 1; j < lines.length && (lines[j].trim() === "" || lines[j].startsWith(">")); j++) if (lines[j].startsWith(">")) words.push(unq(lines[j]));
    break;
  }
  // Shape 2: a bold title `**ID — what it asks.**`, then the owner's selection or quotation, up to `ID STATUS:`.
  if (!words.length) {
    const t = lines.findIndex((l) => new RegExp("^\\*\\*" + id + " [\u2014-]").test(l));
    if (t >= 0) for (let j = t + 1; j < lines.length && !lines[j].startsWith(id + " STATUS:") && !lines[j].startsWith("**"); j++) if (lines[j].trim()) words.push(unq(lines[j]));
  }
  const item = lines.find((l) => new RegExp("^\\d+\\. \\*\\*" + id + "\\.\\*\\*").test(l));
  return { words: words.map(clean), change: item ? clean(item.replace(/^\d+\.\s*/, "")) : null };
}
// s: {key, tag, title, question, ledger, rid}. rid is the id the ledger entry quotes the owner's words under.
function answeredCard(s) {
  const text = META.rulings[s.ledger], { words, change } = text ? rulingParts(s.rid, text) : { words: [], change: null };
  const on = (s.ledger.match(/\d{4}-\d{2}-\d{2}/) || [""])[0];
  return h("details", { class: "prompt", id: "p-" + s.key },
